values ('v4', 'Edale 50km nutrition plan (v4, 12 Nov 2026)', 'Proposed. v4: oats are dry weight (everything else cooked weight). Dinners are 5% beef mince by default (chicken only as a swap), chicken is skinless boneless breast fillet, gels in-run on long runs, chicken + rice afternoon snack, oats/fruit at breakfast, pineapple/honeydew.', '2026-11-09', '2027-09-19', 190.5, 33, 99, 2930, 2520, 410, 155, 170,
  $j${"Mon":"lift_day","Tue":"run_day","Wed":"lift_day","Thu":"run_day","Fri":"lift_day","Sat":"long_run_day","Sun":"sunday"}$j$::jsonb, replace(replace($j${"inputs":{"height_cm":190.5,"start_weight_kg":"98-100 (98.0 on 30 Nov)","age_assumed":33,"bmr_mifflin_kcal":2020,"estimated_weekly_avg_maintenance_kcal":2930,"planned_weekly_avg_kcal":2520,"planned_avg_deficit_kcal":410,"expected_loss_kg_per_week":0.37},"protein_target_g":{"floor":155,"aim":170,"range":"160-190"},"food_rules":["High-protein, whole-food, minimal processed","Staples: 5% beef mince, white rice, sweet potato, eggs, bananas, blueberries, red meat 2+/wk, skinless boneless chicken breast fillet, 5+ fruit/veg a day, peppers always cooked","Added 12 Nov (user request): porridge oats (dry weight, cooked in water, no dairy), pineapple, honeydew melon, energy gels for long runs","No dairy, no protein powder. Skyr/whey occasional only","Supplements: creatine, vitamin D, electrolytes. Pre-training: black coffee, ABE (lift days only), CarbX blackcurrant (pre-training only; gels replace CarbX during long runs)","All weights are cooked weights (meat, rice, veg, sweet potato baked) except oats, which are dry weight","No alcohol (USA fortnight is the one planned exception)","Weigh-ins: morning, before food, after toilet"],"dinner_rule":{"default":"Dinner protein is 5% beef mince.","chicken_swap":"Swap to skinless boneless chicken breast fillet (same cooked weight, about 125 g mince = about 110 g chicken) only when there is a reason: eating out or away, or a day running short on calories where the leaner protein helps. Keep protein at 170 g or more.","note":"Mince is at lunch and dinner. Red meat 2+/wk is easily met."},"treat_slot":{"days":["Fri","Sat"],"rule":"One ice cream max. Swap it for the rice in the afternoon snack and keep the chicken. Never both."},"long_run_scaling":{"reference":"Sat built for 9 mi (14.5 km), about 1 h 45.","kcal_per_extra_mile":125,"carbs_g_per_extra_mile":28,"how":"Add extra rice/sweet potato at Sat lunch and dinner, and extra gels in-run. Protein stays 170-190 g. Add the carbs at lunch and dinner (rice, sweet potato).","gel_note":"A gel is about 22 g carbs and 90 kcal. 2 an hour is about 44 g/h, 3 an hour 66 g/h, 4 an hour 88 g/h. Check your gel brand's carbs and adjust.","in_run_carbs_g_per_hour":{"wk3_9mi":"30-45 (about 2 gels/h)","half_marathon_and_wk6_on":"45-60","specific_block_wk28_on":"60, building to 90 by race day"},"note":"Every long run over about 90 minutes gets fuelled. Train the gut with the race gel."},"phase_rules":[{"weeks":"1-24 (30 Nov - 16 May)","rule":"Deficit as per day types. Weekly average about 2520 kcal."},{"weeks":"25-26 (USA, 17-30 May)","rule":"Maintenance: add about 400 kcal a day. Protein 170 g or more, eat protein first. No drinking the night before a run, run before any drinking, water + electrolytes between drinks, pint of water before bed. Judge return weigh-ins on the second week."},{"weeks":"27 (31 May - 6 Jun)","rule":"Last deficit week. Deficit ends Sun 6 Jun."},{"weeks":"28-42 (7 Jun - 19 Sep)","rule":"No deficit: add about 400 kcal a day to every day type. Sat scales with long-run mileage (peak 21 mi on Sat 28 Aug)."},{"weeks":"Race days","rule":"No deficit. Fuel to the race with gels."},{"weeks":"Down weeks","rule":"No change in food."}],"adjust_rules":["If two weeks in a row D_R_O_P more than 0.6 kg, or long runs feel flat: add 150-200 kcal a day (add carbs, not protein)","Weight targets (Mon mornings): 98.0 (30 Nov), 97.6, 97.2, 96.8, 96.4, 96.0 (Mon 4 Jan checkpoint)","[Proposed] If 0.4 kg or more behind target on two Mondays running with leaks logged as zero, cut 150 kcal from Sunday and run-day carbs"],"assumptions_to_confirm":["Age 33 assumed","Cooking oil (1 tsp per cooked meal) is the only item beyond the named foods","Values are typical UK label averages; cooked weights use a 0.75 cooked-to-raw yield for meat. Swap for your own tracker's figures"]}$j$, 'D_R_O_P', 'dro' || 'p'), 'D_E_L_E_T_E', 'dele' || 'te')::jsonb)
